def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    turn = b / 40.0
    if turn > 1.0:
        turn = 1.0
    if turn < -1.0:
        turn = -1.0

    if abs(b) < 45.0:
        fwd = 1.0
    elif abs(b) < 90.0:
        fwd = 0.6
    else:
        fwd = 0.0

    w = me.weapons.get("front")
    rpm = 0.0
    if w is not None:
        rpm = w.get("rpm", 0.0)
    if abs(rpm) < 2000.0:
        fwd = fwd * 0.5

    r = (me.x * me.x + me.y * me.y) ** 0.5
    if r > 5.0:
        bc = bearing_to(0.0, 0.0)
        turn2 = bc / 45.0
        if turn2 > 1.0:
            turn2 = 1.0
        if turn2 < -1.0:
            turn2 = -1.0
        turn = 0.6 * turn + 0.4 * turn2
        if abs(bc) < 60.0:
            if fwd > 0.5:
                fwd = 0.5

    left = fwd - turn
    right = fwd + turn
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
    return (left, right)

