def drive(me, enemy, arena):
    if me.on_side:
        return None
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    eh = enemy.heading * pi / 180.0
    ex = me.x - enemy.x
    ey = me.y - enemy.y
    fx = cos(eh)
    fy = sin(eh)
    dot = ex * fx + ey * fy
    if dot > 0.1 and dist > 0.8:
        cross = ex * fy - ey * fx
        side = 1.0 if cross > 0 else -1.0
        tx = enemy.x + cos(eh + side * pi / 2.0) * 0.7 - fx * 0.2
        ty = enemy.y + sin(eh + side * pi / 2.0) * 0.7 - fy * 0.2
    else:
        tx = enemy.x
        ty = enemy.y
    r = hypot(me.x, me.y)
    if r > 4.8:
        cx = -me.x
        cy = -me.y
        cr = hypot(cx, cy)
        if cr > 0.01:
            cx = cx / cr
            cy = cy / cr
        vx = tx - me.x
        vy = ty - me.y
        vr = hypot(vx, vy)
        if vr > 0.01:
            vx = vx / vr
            vy = vy / vr
        w = (r - 4.8) / 1.5
        if w > 1.0:
            w = 1.0
        if w < 0.0:
            w = 0.0
        vx = vx * (1.0 - w) + cx * w
        vy = vy * (1.0 - w) + cy * w
        vr = hypot(vx, vy)
        if vr > 0.01:
            vx = vx / vr
            vy = vy / vr
        tx = me.x + vx * 1.0
        ty = me.y + vy * 1.0
    b = bearing_to(tx, ty)
    turn = b / 35.0
    if turn > 1.0:
        turn = 1.0
    if turn < -1.0:
        turn = -1.0
    ab = abs(b)
    if ab < 20.0:
        fwd = 1.0
    elif ab < 45.0:
        fwd = 0.9
    elif ab < 75.0:
        fwd = 0.6
    elif ab < 110.0:
        fwd = 0.3
    else:
        fwd = 0.0
    if dist < 1.8:
        fwd = 1.0
    if me.inverted:
        left = fwd + turn
        right = fwd - turn
    else:
        left = fwd - turn
        right = fwd + turn
    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0
    return (left, right)

